<?php require_once __DIR__.'/../includes/functions.php'; require_login('admin'); $pdo=db(); if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{if($action==='booking'){ $id=(int)$_POST['id'];$status=$_POST['status']??'';if(in_array($status,['approved','rejected'],true)){$s=$pdo->prepare("UPDATE bookings SET status=? WHERE id=? AND status='requested'");$s->execute([$status,$id]);flash('Appointment request updated.');}}elseif($action==='hospital'){ $id=(int)$_POST['id'];$status=$_POST['status']??'';if(in_array($status,['active','inactive'],true)){$pdo->prepare('UPDATE hospitals SET status=? WHERE id=?')->execute([$status,$id]);$pdo->prepare("UPDATE users u JOIN hospitals h ON h.user_id=u.id SET u.status=? WHERE h.id=?")->execute([$status==='active'?'active':'suspended',$id]);flash('Hospital status updated.');}}elseif($action==='create_hospital'){ $userId=(int)($_POST['user_id']??0);$name=trim($_POST['hospital_name']??'');$address=trim($_POST['address']??'');$city=trim($_POST['city']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['hospital_email']??'');if(!$name||!$address||!$city)throw new RuntimeException('Hospital name, address, and city are required.');if($userId){$s=$pdo->prepare("SELECT id FROM users WHERE id=? AND role='hospital'");$s->execute([$userId]);if(!$s->fetch())throw new RuntimeException('Choose a valid hospital account.');}$s=$pdo->prepare("INSERT INTO hospitals(user_id,name,address,city,phone,email,status) VALUES(?,?,?,?,?,?,'active')");$s->execute([$userId?:null,$name,$address,$city,$phone,$email]);if($userId)$pdo->prepare("UPDATE users SET status='active' WHERE id=?")->execute([$userId]);flash('Hospital profile created and activated.');}elseif($action==='vaccine'){ $name=trim($_POST['name']??'');$dose=trim($_POST['dose']??'Dose 1');$age=trim($_POST['age']??'');if($name){$s=$pdo->prepare('INSERT INTO vaccines(name,dose,recommended_age) VALUES(?,?,?)');$s->execute([$name,$dose,$age]);flash('Vaccine added to catalogue.');}}elseif($action==='link_vaccine'){ $hid=(int)($_POST['hospital_id']??0);$vid=(int)($_POST['vaccine_id']??0);$status=$_POST['availability']??'available';if(!in_array($status,['available','unavailable'],true))throw new RuntimeException('Invalid availability.');$s=$pdo->prepare('INSERT INTO hospital_vaccines(hospital_id,vaccine_id,status) VALUES(?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status)');$s->execute([$hid,$vid,$status]);flash('Hospital vaccine availability saved.');}elseif($action==='vaccine_status'){$id=(int)$_POST['id'];$status=$_POST['status']??'';if(in_array($status,['available','unavailable'],true)){$pdo->prepare('UPDATE vaccines SET status=? WHERE id=?')->execute([$status,$id]);flash('Vaccine availability updated.');}}}catch(PDOException $ex){flash('Could not complete that action. Check for duplicate vaccine entries or related bookings.','error');}redirect('/admin/manage.php');}
$bookings=$pdo->query("SELECT b.*,c.full_name child_name,u.name parent_name,h.name hospital_name,v.name vaccine_name FROM bookings b JOIN children c ON c.id=b.child_id JOIN users u ON u.id=b.parent_id JOIN hospitals h ON h.id=b.hospital_id JOIN vaccines v ON v.id=b.vaccine_id ORDER BY b.created_at DESC")->fetchAll();$hospitals=$pdo->query('SELECT h.*,u.email account_email FROM hospitals h LEFT JOIN users u ON u.id=h.user_id ORDER BY h.created_at DESC')->fetchAll();$vaccines=$pdo->query('SELECT * FROM vaccines ORDER BY name,dose')->fetchAll();$children=$pdo->query('SELECT c.*,u.name parent_name FROM children c JOIN users u ON u.id=c.parent_id ORDER BY c.created_at DESC')->fetchAll();$pending=$pdo->query("SELECT id,name,email,created_at FROM users WHERE role='hospital' AND status='pending'")->fetchAll();$pageTitle='Manage system';require __DIR__.'/../includes/header.php';?>
<div class="dashboard-head"><div><span class="eyebrow">ADMIN TOOLS</span><h1>Manage the system</h1><p>Review appointments, hospitals, children, and vaccine availability.</p></div><a class="button secondary" href="<?=BASE_URL?>/admin/index.php">← Dashboard</a></div>
<?php if($pending):?><section class="panel" id="hospital-accounts"><div class="panel-head"><div><h2>Pending hospital accounts</h2><p>Activate an account by adding its hospital profile below, then set the hospital active.</p></div></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Requested</th><th>Action</th></tr></thead><tbody><?php foreach($pending as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['created_at'])?></td><td><a class="button small secondary" href="#hospitals">Add hospital profile below</a></td></tr><?php endforeach;?></tbody></table></div><p class="muted">To link a hospital login, create its hospital profile in the database with the matching user_id, then activate it here. See README for details.</p></section><?php endif;?>
<section class="panel" id="bookings"><div class="panel-head"><div><h2>Appointment requests</h2><p>Approve or reject requests that are waiting for a decision.</p></div></div><div class="table-wrap"><table><thead><tr><th>Child / parent</th><th>Vaccine</th><th>Hospital</th><th>Schedule</th><th>Status / action</th></tr></thead><tbody><?php if(!$bookings):?><tr><td colspan="5" class="empty">No appointment requests yet.</td></tr><?php endif;foreach($bookings as $b):?><tr><td><b><?=e($b['child_name'])?></b><br><small><?=e($b['parent_name'])?></small></td><td><?=e($b['vaccine_name'])?></td><td><?=e($b['hospital_name'])?></td><td><?=e($b['appointment_date'])?><br><?=e(substr($b['appointment_time'],0,5))?></td><td><span class="badge <?=e($b['status'])?>"><?=e(ucfirst($b['status']))?></span><?php if($b['status']==='requested'):?><form class="inline-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="booking"><input type="hidden" name="id" value="<?=$b['id']?>"><button class="button small" name="status" value="approved">Approve</button><button class="button small danger" name="status" value="rejected">Reject</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel" id="hospitals"><div class="panel-head"><div><h2>Add hospital profile</h2><p>Link a registered hospital account if applicable, or create a directory-only hospital.</p></div></div><form class="data-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create_hospital"><label>Hospital name<input name="hospital_name" required maxlength="160"></label><label>Registered hospital account<select name="user_id"><option value="0">No login account (directory only)</option><?php foreach($pending as $pu):?><option value="<?=$pu['id']?>"><?=e($pu['name'].' · '.$pu['email'])?></option><?php endforeach;?></select></label><label>Address<input name="address" required maxlength="255"></label><label>City<input name="city" required maxlength="100"></label><label>Phone<input name="phone" maxlength="30"></label><label>Contact email<input type="email" name="hospital_email" maxlength="190"></label><div class="wide"><button class="button primary">Create and activate hospital →</button></div></form><div class="panel-head" style="margin-top:25px"><div><h2>Hospital directory</h2><p>Review and activate registered hospital listings.</p></div></div><div class="table-wrap"><table><thead><tr><th>Hospital</th><th>Location</th><th>Contact</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$hospitals):?><tr><td colspan="5" class="empty">No hospital records yet. Insert hospital profiles using the setup instructions in README.</td></tr><?php endif;foreach($hospitals as $h):?><tr><td><b><?=e($h['name'])?></b></td><td><?=e($h['address'])?>, <?=e($h['city'])?></td><td><?=e($h['phone']??'—')?><br><?=e($h['email']??$h['account_email']??'—')?></td><td><span class="badge <?=e($h['status'])?>"><?=e(ucfirst($h['status']))?></span></td><td><?php if($h['status']!=='active'):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="hospital"><input type="hidden" name="id" value="<?=$h['id']?>"><button class="button small" name="status" value="active">Activate</button></form><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="hospital"><input type="hidden" name="id" value="<?=$h['id']?>"><button class="button small danger" name="status" value="inactive">Deactivate</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel" id="vaccines"><div class="panel-head"><div><h2>Configure hospital vaccine availability</h2><p>Choose which vaccines a hospital offers; hospitals can update availability in their portal.</p></div></div><form class="data-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="link_vaccine"><label>Hospital<select name="hospital_id" required><?php foreach($hospitals as $h):?><option value="<?=$h['id']?>"><?=e($h['name'])?></option><?php endforeach;?></select></label><label>Vaccine<select name="vaccine_id" required><?php foreach($vaccines as $v):?><option value="<?=$v['id']?>"><?=e($v['name'].' — '.$v['dose'])?></option><?php endforeach;?></select></label><label>Initial availability<select name="availability"><option value="available">Available</option><option value="unavailable">Unavailable</option></select></label><div class="wide"><button class="button primary">Save hospital vaccine →</button></div></form><div class="panel-head" style="margin-top:26px"><div><h2>Vaccine catalogue</h2><p>Illustrative vaccine list; confirm clinical schedules with local health authorities.</p></div></div><form class="data-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="vaccine"><label>Vaccine name<input name="name" required placeholder="e.g. Example vaccine"></label><label>Dose<input name="dose" value="Dose 1" required></label><label>Recommended age<input name="age" placeholder="e.g. 6 weeks"></label><div class="wide"><button class="button primary">Add vaccine</button></div></form><div class="table-wrap"><table><thead><tr><th>Vaccine</th><th>Dose</th><th>Recommended age</th><th>Availability</th><th>Action</th></tr></thead><tbody><?php foreach($vaccines as $v):?><tr><td><?=e($v['name'])?></td><td><?=e($v['dose'])?></td><td><?=e($v['recommended_age']??'—')?></td><td><span class="badge <?=e($v['status'])?>"><?=e(ucfirst($v['status']))?></span></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="vaccine_status"><input type="hidden" name="id" value="<?=$v['id']?>"><button class="button small secondary" name="status" value="<?=$v['status']==='available'?'unavailable':'available'?>">Mark <?=$v['status']==='available'?'unavailable':'available'?></button></form></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><div class="panel-head"><div><h2>Child directory</h2><p>Child records currently registered by parents.</p></div></div><div class="table-wrap"><table><thead><tr><th>Child</th><th>Parent</th><th>Date of birth</th><th>Gender</th><th>Guardian phone</th></tr></thead><tbody><?php if(!$children):?><tr><td colspan="5" class="empty">No child profiles yet.</td></tr><?php endif;foreach($children as $c):?><tr><td><?=e($c['full_name'])?></td><td><?=e($c['parent_name'])?></td><td><?=e($c['date_of_birth'])?></td><td><?=e(ucfirst($c['gender']))?></td><td><?=e($c['guardian_phone']??'—')?></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php';?>
